// Turn each CSV row into one clean item per company, keyed by domain.
// Works with Apollo's export headers or the simple template (name, domain, headcount, country, industry).
const key = (s) => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
const pick = (row, names) => {
  const wanted = names.map(key);
  for (const [k, v] of Object.entries(row)) {
    if (wanted.includes(key(k)) && String(v ?? '').trim() !== '') return String(v).trim();
  }
  return '';
};
const normaliseDomain = (raw) => (raw || '')
  .toLowerCase().trim()
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .replace(/\/.*$/, '');

const seen = new Set();
const out = [];
for (const { json: row } of $input.all()) {
  const domain = normaliseDomain(pick(row, ['domain', 'website', 'company website', 'primary domain']));
  if (!domain || seen.has(domain)) continue;
  seen.add(domain);
  const headcount = parseInt(pick(row, ['headcount', '# employees', 'employees', 'number of employees']).replace(/[^0-9]/g, ''), 10);
  out.push({
    json: {
      name: pick(row, ['name', 'company', 'company name', 'account name']),
      domain,
      website: `https://${domain}`,
      headcount: Number.isNaN(headcount) ? null : headcount,
      country: pick(row, ['country', 'company country', 'hq country']),
      industry: pick(row, ['industry']),
    },
  });
}
return out;

// Drop companies whose website is already on an Account in Salesforce.
const normaliseDomain = (raw) => (raw || '')
  .toLowerCase().trim()
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .replace(/\/.*$/, '');

const existing = new Set(
  $input.all().map((i) => normaliseDomain(i.json.Website)).filter(Boolean),
);
const companies = $('Normalise companies').all();
const fresh = companies.filter((i) => !existing.has(i.json.domain));

console.log(`${companies.length} from source, ${companies.length - fresh.length} already in Salesforce, ${fresh.length} new`);
return fresh.map((i) => ({ json: i.json }));
